    (task_name, template_text, version, is_active, description, language_id, model, provider, tier_id)
SELECT b.task_name,
       b.template_text || E'\n\n' || $lvl$**LEVEL REQUIREMENTS (T3) — these override any difficulty guidance above**
- Use clear, everyday English (CEFR B1). Avoid academic phrasing that is not in the passage.
- The question is at most 14 words; each choice at most 10 words.
- Keep all four choices similar in length and form; the correct answer must not be clearly the longest.
- For a reason or example question, the correct answer is the reason the passage gives, briefly paraphrased.
- Return ONLY the JSON object shown above, no additional text.$lvl$,
       103, true,
       'ADR-040 T3 level template (base v' || b.version || ' + level block)',
       b.language_id, b.model, b.provider, 3
FROM (
    SELECT * FROM public.prompt_templates
    WHERE task_name = 'question_supporting_detail' AND language_id = 2
      AND is_active AND tier_id IS NULL
    ORDER BY version DESC LIMIT 1
) b
WHERE NOT EXISTS (
    SELECT 1 FROM public.prompt_templates
    WHERE task_name = 'question_supporting_detail' AND language_id = 2 AND tier_id = 3
);

-- ja T1 question_literal_detail
INSERT INTO public.prompt_templates
    (task_name, template_text, version, is_active, description, language_id, model, provider, tier_id)
SELECT b.task_name,
       b.template_text || E'\n\n' || $lvl$【レベル別の要件（初級・T1）— 上の難易度の指示より、こちらを優先すること】
・質問文・選択肢・解説は、ひらがなとカタカナで書くこと。漢字は、資料の本文に出てくる漢字だけ使ってよい。
・資料が分かち書き（ことばの間に空白）なら、質問文と選択肢も同じように分かち書きにすること。
・質問文は25字以内の短くやさしい文にすること。「文中の」「最も適切なもの」「選んでください」などのかたい言い方は使わないこと。例：「ロボットはどこでてつだいをしますか。」
・選択肢は15字以内の短い語句にし、四つとも同じ形（名詞なら名詞）にそろえること。
・正解は資料にはっきり書いてあることにすること。まちがいの選択肢も、資料の話題に関係のある、もっともらしいものにすること。
・出力は、上に示した JSON オブジェクトのみとすること。$lvl$,
       101, true,
       'ADR-040 T1 level template (base v' || b.version || ' + level block)',
       b.language_id, b.model, b.provider, 1
FROM (
    SELECT * FROM public.prompt_templates
    WHERE task_name = 'question_literal_detail' AND language_id = 3
      AND is_active AND tier_id IS NULL
    ORDER BY version DESC LIMIT 1
) b
WHERE NOT EXISTS (
    SELECT 1 FROM public.prompt_templates
    WHERE task_name = 'question_literal_detail' AND language_id = 3 AND tier_id = 1
);

-- ja T1 question_vocabulary_context
INSERT INTO public.prompt_templates
    (task_name, template_text, version, is_active, description, language_id, model, provider, tier_id)
