    SELECT * FROM public.prompt_templates
    WHERE task_name = 'question_vocabulary_context' AND language_id = 3
      AND is_active AND tier_id IS NULL
    ORDER BY version DESC LIMIT 1
) b
WHERE NOT EXISTS (
    SELECT 1 FROM public.prompt_templates
    WHERE task_name = 'question_vocabulary_context' AND language_id = 3 AND tier_id = 1
